changeSet.sql:
-- New nullable context columns.
ALTER TABLE note ADD COLUMN manuscript_id INTEGER
    REFERENCES manuscript(manuscript_id) ON DELETE SET NULL;
ALTER TABLE note ADD COLUMN scratchpad_id INTEGER
    REFERENCES scratchpad(scratchpad_id) ON DELETE SET NULL;

-- A note no longer requires a sentence.
ALTER TABLE note ALTER COLUMN sentence_id DROP NOT NULL;

-- Backfill manuscript_id for existing sentence notes from the
-- sentence -> migration -> manuscript chain (the authoritative
-- link is the sentence row's migration, not the id string).
UPDATE note n
SET manuscript_id = m.manuscript_id
FROM sentence s
JOIN migration m ON m.migration_id = s.migration_id
WHERE n.sentence_id IS NOT NULL
  AND s.sentence_id = n.sentence_id
  AND n.manuscript_id IS NULL;

-- Indexes for the landing-grid / context queries.
CREATE INDEX idx_note_manuscript ON note(manuscript_id) WHERE manuscript_id IS NOT NULL;
CREATE INDEX idx_note_scratchpad ON note(scratchpad_id) WHERE scratchpad_id IS NOT NULL;
-- User-owned recency ordering for the landing grid (active notes).
CREATE INDEX idx_note_user_updated ON note(user_id, updated_at DESC) WHERE deleted_at IS NULL;
